public readonly record struct Money(long Minor, Currency Currency)
{
    public static Money operator +(Money a, Money b) =>
        a.Currency == b.Currency
            ? new Money(a.Minor + b.Minor, a.Currency)
            : throw new InvalidOperationException("currency mismatch");

    public static Money operator *(Money m, int factor) => m with { Minor = m.Minor * factor };

    public static Money Zero(Currency c) => new(0, c);   // identity element
}

